let nextTestServerPort = 23000;

function nextSafeTestServerPort() {
  const port = nextTestServerPort;
  nextTestServerPort += 1;
  if (nextTestServerPort > 55000) {
    nextTestServerPort = 23000;
  }
  return port;
}

async function listenOnSafeTestPort(server) {
  for (let attempt = 0; attempt < 80; attempt += 1) {
    const port = nextSafeTestServerPort();
    const result = await new Promise((resolve) => {
      const onError = (error) => {
        server.off('listening', onListening);
        resolve({ ok: false, error });
      };
      const onListening = () => {
        server.off('error', onError);
        resolve({ ok: true, address: server.address() });
      };
      server.once('error', onError);
      server.once('listening', onListening);
      server.listen(port, '127.0.0.1');
    });

    if (result.ok) {
      return result.address;
    }
    if (!['EADDRINUSE', 'EACCES'].includes(result.error?.code)) {
      throw result.error;
    }
  }
  throw new Error('Unable to bind a safe local test server port.');
}

async function withServer(server, run) {
  const address = await listenOnSafeTestPort(server);
  const baseUrl = `http://127.0.0.1:${address.port}`;
  try {
    return await run(baseUrl);
  } finally {
    await new Promise((resolve, reject) => server.close((error) => (error ? reject(error) : resolve())));
  }
}

async function postJson(url, body, token) {
  const response = await fetch(url, {
    method: 'POST',
    headers: {
      'content-type': 'application/json',
      ...(token ? { authorization: `Bearer ${token}` } : {})
    },
    body: JSON.stringify(body)
  });
  return response.json();
}

async function getJson(url, token) {
  const response = await fetch(url, {
    headers: token ? { authorization: `Bearer ${token}` } : {}
  });
  return response.json();
}

async function waitForWebSocketOpen(socket, timeoutMs = 3000) {
  if (socket.readyState === WebSocket.OPEN) return true;
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      cleanup();
      reject(new Error('websocket-open-timeout'));
    }, timeoutMs);
    const cleanup = () => {
      clearTimeout(timeout);
      socket.removeEventListener('open', onOpen);
      socket.removeEventListener('error', onError);
    };
    const onOpen = () => {
      cleanup();
      resolve(true);
    };
    const onError = () => {
      cleanup();
      reject(new Error('websocket-open-error'));
    };
    socket.addEventListener('open', onOpen);
    socket.addEventListener('error', onError);
  });
}

async function waitForWebSocketJson(socket, predicate = () => true, timeoutMs = 3000) {
  return new Promise((resolve, reject) => {
    const timeout = setTimeout(() => {
      cleanup();
      reject(new Error('websocket-message-timeout'));
    }, timeoutMs);
    const cleanup = () => {
      clearTimeout(timeout);
      socket.removeEventListener('message', onMessage);
      socket.removeEventListener('error', onError);
    };
    const onMessage = (event) => {
      let payload = null;
      try {
        payload = JSON.parse(String(event.data));
      } catch {
        return;
      }
      if (predicate(payload)) {
        cleanup();
        resolve(payload);
      }
    };
    const onError = () => {
      cleanup();
      reject(new Error('websocket-message-error'));
    };
    socket.addEventListener('message', onMessage);
    socket.addEventListener('error', onError);
  });
}

async function pathExists(path) {
  try {
    await access(path);
    return true;
  } catch {
    return false;
  }
}

function jsonResponse(payload, { status = 200, ok = status < 400 } = {}) {
  return {
    status,
    ok,
    async text() {
      return JSON.stringify(payload);
    }
  };
}

function dirPathForTest(name) {
  return join(tmpdir(), `jarvis-${name}`);
}

await test('PC confirmation console accepts and rejects high-risk approval handoffs', () => {
  const system = createJarvisSystem();
  const initial = system.composeDashboardState('밴드에 전송해');
  assert.equal(initial.pcConsole.pending, 2);
  assert.equal(initial.pcConsole.items.some((item) => item.status === 'awaiting_pc_confirmation'), true);
  const initialVisual = createPcConsoleVisualSnapshot(initial.pcConsole);
  const initialVisualRegression = diffPcConsoleVisualSnapshots(createPcConsoleVisualBaseline(), initialVisual);
  assert.equal(initialVisual.snapshotVersion, 'c-pc-console-visual-snapshot-v1');
  assert.equal(initialVisualRegression.status, 'passed');
  assert.equal(initialVisualRegression.checks.some((check) => check.id === 'accept-reject-actions-visible' && check.passed), true);

  const first = initial.pcConsole.items[0];
  const accepted = system.decidePcConsoleHandoff(first.handoffId, 'approve', { operatorId: 'pc-admin' });
  assert.equal(accepted.success, true);
  assert.equal(accepted.handoff.status, 'accepted');

  const afterAccept = system.composeDashboardState('밴드에 전송해');
  assert.equal(afterAccept.pcConsole.accepted, 1);
  assert.equal(afterAccept.pcConsole.lastDecision.decision, 'approve');
  assert.equal(afterAccept.auditEvents.some((event) => event.event === 'pc_console.handoff_decided'), true);

  const second = afterAccept.pcConsole.items.find((item) => item.status === 'awaiting_pc_confirmation');
  const rejected = system.decidePcConsoleHandoff(second.handoffId, 'reject', { operatorId: 'pc-admin', note: '외부 전송 대상 미확인' });
  assert.equal(rejected.success, true);
  assert.equal(rejected.handoff.status, 'rejected');

  const afterReject = system.composeDashboardState('밴드에 전송해');
  assert.equal(afterReject.pcConsole.pending, 0);
  assert.equal(afterReject.pcConsole.rejected, 1);
  const decidedVisualRegression = diffPcConsoleVisualSnapshots(
    createPcConsoleVisualBaseline({ minAwaitingRows: 0 }),
    createPcConsoleVisualSnapshot(afterReject.pcConsole)
  );
  assert.equal(decidedVisualRegression.status, 'passed');
  assert.equal(decidedVisualRegression.checks.some((check) => check.id === 'decided-rows-hide-live-actions' && check.passed), true);
});

await test('A core creates a document-aligned task, policy result, and approval card', () => {
  const { coreFacade } = createAgRuntime();
  const task = coreFacade.createTask('엑셀 만들어');

  assert.equal(task.status, TaskStatus.WAITING_APPROVAL);
  assert.equal(task.request.source.type, InputSource.MOBILE);
  assert.equal(task.plan.action.actionType, ActionType.CREATE_FILE);
  assert.equal(task.plan.action.toolName, 'excel.createWorkbook');
  assert.equal(task.plan.action.arguments.outputFormat, 'xlsx');
  assert.equal(task.plan.planGraph.strategy, 'single_action_linear');
  assert.equal(task.plan.planGraph.invariants.includes('No B module mutation before approval.'), true);
  assert.equal(task.plan.failureBranches.some((branch) => branch.branchId === 'failure_execution_partial'), true);
  assert.equal(task.plan.compensationPlan.evidenceRequired.includes('UndoJournal'), true);
  assert.equal(task.contextSnapshot.taskId, task.taskId);
  assert.equal(task.ambiguity.ambiguous, false);
  assert.equal(task.intent.confidence >= 0.75, true);
  assert.equal(task.intent.slots.outputFormat, 'xlsx');
  assert.equal(task.plan.planSteps.every((step) => Number.isInteger(step.order)), true);
  assert.equal(task.plan.planSteps.every((step) => Array.isArray(step.preconditions)), true);
  assert.equal(task.orchestrationTrace.steps.some((step) => step.phase === 'task.created'), true);
  assert.equal(task.approvalCard.riskTier, 5);
  assert.equal(task.approvalCard.externalTransfer, false);
  assert.equal(task.approvalCard.rollbackAvailable, true);
  assert.ok(task.approvalCard.planSteps.length >= 4);
  assert.equal(coreFacade.eventBus.recent().some((event) => event.eventType === 'approval.card.created'), true);
  assert.equal(task.lifecycle.current().status, TaskStatus.WAITING_APPROVAL);
  assert.equal(task.lifecycle.progress().currentStep, '승인 대기');
});

await test('A CoreFacade preserves Control Center source metadata on task creation', () => {
  const { coreFacade } = createAgRuntime();
  const task = coreFacade.createTask('파일 목록 보여줘', {
    source: InputSource.PC_UI,
    sourceModule: ModuleId.PC_AGENT,
    deviceId: 'local-control-center',
    inputMode: 'text',
    userId: 'local_operator',
    locale: 'ko-KR',
    attachments: [{ attachmentId: 'att_control_center', kind: 'context' }],
    metadata: {
      submittedBy: 'jarvis-control-center',
      surface: 'desktop'
    }
  });

  assert.equal(task.request.source.type, InputSource.PC_UI);
  assert.equal(task.request.source.module, ModuleId.PC_AGENT);
  assert.equal(task.request.source.deviceId, 'local-control-center');
  assert.equal(task.request.source.inputMode, 'text');
  assert.equal(task.request.userId, 'local_operator');
  assert.equal(task.request.command.locale, 'ko-KR');
  assert.equal(task.request.attachments[0].attachmentId, 'att_control_center');
  assert.equal(task.request.metadata.submittedBy, 'jarvis-control-center');
  assert.equal(task.request.metadata.surface, 'desktop');
});

await test('A CoreFacade avoids task id collisions for duplicate same-millisecond commands', () => {
  const { coreFacade } = createAgRuntime({ clock: () => new Date('2026-06-21T00:00:00.000Z') });
  const first = coreFacade.createTask('파일 목록 보여줘');
  const second = coreFacade.createTask('파일 목록 보여줘');

  assert.notEqual(first.taskId, second.taskId);
  assert.notEqual(first.request.requestId, second.request.requestId);
  assert.equal(second.request.metadata.idCollisionAvoided, true);
  assert.equal(second.request.metadata.originalTaskId, first.taskId);
  assert.equal(second.plan.taskId, second.taskId);
  assert.equal(second.contextSnapshot.taskId, second.taskId);
  assert.equal(coreFacade.tasks.size, 2);
});

await test('shared JSONL write classifier treats Windows file locks as transient only', () => {
  assert.equal(isTransientJsonlWriteError({ code: 'EBUSY' }), true);
  assert.equal(isTransientJsonlWriteError({ code: 'EPERM' }), true);
  assert.equal(isTransientJsonlWriteError({ code: 'EACCES' }), true);
  assert.equal(isTransientJsonlWriteError({ code: 'ENOENT' }), false);
  assert.equal(isTransientJsonlWriteError({ code: 'EISDIR' }), false);
});

