await test('A SemanticIntentAdapter recovers paraphrased commands and compares against the rule parser', async () => {
  const standardCorpus = JSON.parse(await readFile(join('packages', 'core', 'fixtures', 'intent-command-corpus.json'), 'utf8'));
  const semanticCorpus = JSON.parse(await readFile(join('packages', 'core', 'fixtures', 'intent-semantic-command-corpus.json'), 'utf8'));
  const ruleParser = new IntentParser();
  const semanticAdapter = new LocalSemanticIntentAdapter({ parser: ruleParser });
  const comparison = evaluateIntentCorpusWithSemantic(standardCorpus, {
    ruleParser,
    semanticAdapter,
    createdAt: '2026-06-18T00:00:00.000Z'
  });
  const semanticReport = evaluateIntentCorpus(semanticCorpus, {
    parser: semanticAdapter,
    createdAt: '2026-06-18T00:00:00.000Z'
  });
  const ruleBaseline = evaluateIntentCorpus(semanticCorpus, {
    parser: ruleParser,
    thresholds: {
      intentAccuracy: 0,
      slotAccuracy: 0,
      entityAccuracy: 0,
      complexityAccuracy: 0,
      combinedAccuracy: 0
    },
    createdAt: '2026-06-18T00:00:00.000Z'
  });

  assert.equal(comparison.passed, true, JSON.stringify(comparison.disagreements, null, 2));
  assert.equal(comparison.version, 'intent-corpus-semantic-comparison-v1');
  assert.equal(comparison.semanticReport.metrics.intentAccuracy, 1);
  assert.equal(comparison.agreement, 1);
  assert.equal(semanticReport.passed, true, JSON.stringify(semanticReport.failures, null, 2));
  assert.equal(semanticReport.metrics.intentAccuracy, 1);
  assert.equal(ruleBaseline.metrics.intentAccuracy < semanticReport.metrics.intentAccuracy, true);
  const naturalList = semanticAdapter.parse('작업공간 안에 뭐가 있는지 확인해줘', {
    requestId: 'semantic_natural_list',
    createdAt: '2026-06-18T00:00:00.000Z'
  });
  assert.equal(naturalList.actionType, ActionType.LIST_FILES);
  assert.equal(naturalList.semantic.matched, true);
  assert.equal(naturalList.semantic.adapterId, 'local-semantic-intent-adapter-v1');
});

await test('A approved intent logs build anonymized drift calibration corpus', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a03-intent-log-'));
  try {
    const ruleParser = new IntentParser();
    const localAdapter = new LocalSemanticIntentAdapter({ parser: ruleParser });
    const externalAdapter = {
      adapterId: 'fixture-external-semantic-intent-adapter-v1',
      parse(rawText, options = {}) {
        const parsed = localAdapter.parse(rawText, options);
        return {
          ...parsed,
          confidence: Math.min(0.98, Number(parsed.confidence ?? 0) + 0.08),
          semantic: {
            ...(parsed.semantic ?? {}),
            adapterId: 'fixture-external-semantic-intent-adapter-v1',
            provider: 'approved-log-fixture'
          }
        };
      }
    };
    const gatedAdapter = new PolicyGatedSemanticIntentAdapter({
      localAdapter,
      externalAdapter,
      externalEnabled: true,
      minLocalConfidence: 0.99
    });
    const store = new ApprovedIntentLogStore({
      filePath: join(dir, 'approved-intent-log.jsonl'),
      clock: () => new Date('2026-06-22T00:00:00.000Z')
    });
    const rejected = store.record({
      command: '승인 없이 저장하면 안 되는 명령',
      expected: { actionType: ActionType.CREATE_FILE }
    });
    assert.equal(rejected.success, false);

    const upload = store.record({
      command: '고객 jang@example.com 010-1234-5678에게 보고서를 이메일로 보내줘',
      expected: { actionType: ActionType.SEND_EMAIL },
      approvedForLearning: true,
      approvalId: 'appr_a03_log_upload',
      taskId: 'task_a03_log_upload',
      source: 'mobile-approved-command'
    });
    store.record({
      command: '지난 회의 자료를 아카이브로 옮겨줘',
      expected: { actionType: ActionType.MOVE_FILE },
      approvedForLearning: true,
      approvalId: 'appr_a03_log_move',
      source: 'pc-approved-command'
    });
    store.record({
      command: '이번 주 예배 안내문 만들어줘',
      expected: { actionType: ActionType.CREATE_FILE },
      approvedForLearning: true,
      approvalId: 'appr_a03_log_create',
      source: 'mobile-approved-command'
    });

    assert.equal(upload.success, true);
    assert.equal(upload.entry.rawCommandStored, false);
    assert.equal(upload.entry.redactedCommand.includes('jang@example.com'), false);
    assert.equal(upload.entry.redactedCommand.includes('010-1234-5678'), false);
    assert.equal(upload.entry.redactions.some((item) => item.type === 'email'), true);
    assert.equal(upload.entry.redactions.some((item) => item.type === 'phone'), true);

    const corpus = store.toCorpus();
    assert.equal(corpus.version, 'a-03-approved-intent-log-corpus-v1');
    assert.equal(corpus.source.rawCommandsStored, false);
    assert.equal(corpus.fixtures.length, 3);
    assert.equal(corpus.fixtures.every((fixture) => /^[a-f0-9]{64}$/i.test(fixture.source.commandHash)), true);

    const drift = evaluateApprovedIntentDrift({
      store,
      ruleParser,
      semanticAdapter: gatedAdapter,
      externalAdapter,
      createdAt: '2026-06-22T00:00:00.000Z'
    });
    assert.equal(drift.reportVersion, 'a-03-intent-drift-calibration-report-v1');
    assert.equal(drift.passed, true, JSON.stringify(drift.calibration, null, 2));
    assert.equal(drift.rawCommandsStored, false);
    assert.equal(drift.privacy.redactedFixtureCount >= 1, true);
    assert.equal(drift.privacy.commandHashOnly, true);
    assert.equal(drift.comparison.semanticReport.metrics.intentAccuracy, 1);
    assert.equal(drift.externalReport.fixtureCount, 3);
    assert.equal(drift.calibration.every((item) => item.semanticGate?.externalEnabled === true), true);
    assert.equal(drift.externalProvider.adapterId, 'fixture-external-semantic-intent-adapter-v1');
    const actionDriftTrend = createIntentActionDriftTrend({
      currentReport: drift,
      previousReports: [drift]
    });
    assert.equal(actionDriftTrend.trendVersion, 'a-03-intent-action-drift-trend-v1');
    assert.equal(actionDriftTrend.status, 'passed');
    assert.equal(actionDriftTrend.items.some((item) => item.actionType === ActionType.SEND_EMAIL && item.semanticPassRate === 1), true);
    const providerTelemetryDashboard = createSemanticProviderTelemetryDashboard({
      report: drift,
      providers: [
        {
          providerId: 'fixture-external-semantic-intent-adapter-v1',
          providerKind: 'external-shadow',
          enabled: true,
          shadowMode: true,
          p95LatencyMs: 240,
          avgLatencyMs: 140,
          estimatedCostUsd: 0.018,
          regressionDelta: 0,
          rawPromptsStored: false
        }
      ]
    });
    assert.equal(providerTelemetryDashboard.dashboardVersion, 'a-03-semantic-provider-telemetry-dashboard-v1');
    assert.equal(providerTelemetryDashboard.status, 'passed');
    assert.equal(providerTelemetryDashboard.providers.some((provider) => provider.providerId === 'fixture-external-semantic-intent-adapter-v1' && provider.shadowMode === true), true);
    const productGate = createIntentParserProductGate({
      driftReport: drift,
      actionDriftTrend,
      providerTelemetryDashboard
    });
    assert.equal(productGate.productGateVersion, 'a-03-intent-parser-product-gate-v1');
    assert.equal(productGate.status, 'passed');
    assert.equal(productGate.releaseDossier.dossierVersion, 'a-03-intent-parser-release-dossier-v1');
    assert.equal(productGate.releaseDossier.artifactManifest.artifactManifestVersion, 'a-03-intent-parser-release-artifact-manifest-v1');
    assert.equal(productGate.releaseDossier.artifactManifest.rawLeakCheck.rawLeakDetected, false);
    assert.equal(productGate.releaseDossier.artifactManifest.providerContractManifest.manifestVersion, 'a-03-semantic-provider-contract-manifest-v1');
    assert.equal(productGate.releaseDossier.ciNightlyGatePlan.planVersion, 'a-03-intent-parser-ci-nightly-gate-plan-v1');
    assert.equal(productGate.releaseDossier.operationalHandoffManifest.manifestVersion, 'a-03-semantic-provider-operational-handoff-manifest-v1');
    assert.equal(productGate.releaseDossier.operationalHandoffManifest.healthHandshakeVersion, 'a-03-semantic-provider-health-handshake-v1');
    assert.equal(productGate.releaseDossier.operationalHandoffManifest.fallbackPolicy.policyVersion, 'a-03-semantic-provider-fallback-policy-v1');
    assert.equal(productGate.releaseDossier.operationalHandoffManifest.status, 'ready');
    assert.equal(productGate.releaseDossier.operationalHandoffManifest.rawProviderSecretsStored, false);
    assert.equal(productGate.releaseDossier.externalWormPromotionPackage.packageVersion, 'a-03-intent-parser-worm-promotion-package-v1');
    assert.equal(productGate.releaseDossier.externalWormPromotionPackage.providerContractVersion, 'a-03-intent-parser-worm-provider-contract-v1');
    assert.equal(productGate.releaseDossier.externalWormPromotionPackage.status, 'ready');
    assert.equal(productGate.checks.some((check) => check.checkId === 'semantic_provider_telemetry_dashboard_ready' && check.passed), true);
    assert.equal(productGate.checks.some((check) => check.checkId === 'intent_semantic_provider_operational_handoff_ready' && check.passed), true);
    assert.equal(productGate.checks.some((check) => check.checkId === 'intent_worm_promotion_package_ready' && check.passed), true);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

