await test('A TaskPlanner builds multi-action DAG, failure branches, and compensation plan for complex commands', () => {
  const { coreFacade } = createAgRuntime();
  const task = coreFacade.createTask('엑셀 보고서 만들고 그리고 안내문 작성해', {
    createdAt: '2026-06-08T00:00:00.000Z'
  });

  assert.equal(task.intent.complexity.needsPlanDecomposition, true);
  assert.equal(task.plan.planGraph.strategy, 'multi_action_dag');
  assert.equal(task.plan.planGraph.nodes.filter((node) => node.nodeId.startsWith('action_')).length >= 2, true);
  assert.equal(task.plan.planGraph.edges.some((edge) => edge.from === 'action_1' && edge.to === 'action_2'), true);
  assert.equal(task.plan.planGraph.scheduler.scheduleVersion, 'a-plan-parallel-dag-scheduler-v1');
  assert.equal(task.plan.planGraph.scheduler.mode, 'sequential_safe');
  assert.equal(task.plan.planGraph.scheduler.waves.every((wave) => wave.nodeIds.length === 1), true);
  assert.equal(task.plan.failureBranches.some((branch) => branch.branchId === 'failure_dag_node_failed'), true);
  assert.equal(task.plan.failureBranches.some((branch) => branch.blockedNodePolicy === 'skip_descendants'), true);
  assert.equal(task.plan.compensationPlan.strategy, 'rollback_or_manual_review');
  assert.equal(task.plan.compensationPlan.compensatingActions.some((item) => item.safeMode === 'approval_required_before_compensation'), true);
  assert.equal(coreFacade.contractRegistry.validate('TaskPlan', task.plan).valid, true);

  const parallelTask = coreFacade.createTask('첫 파일 만들고 그리고 동시에 두번째 파일 만들고 그리고 동시에 세번째 파일 만들어', {
    createdAt: '2026-06-08T00:00:01.000Z'
  });
  assert.equal(parallelTask.plan.planGraph.scheduler.mode, 'parallel_ready');
  assert.equal(parallelTask.plan.planGraph.scheduler.waves.some((wave) => wave.parallelizable), true);
  assert.equal(parallelTask.plan.planGraph.edges.some((edge) => edge.dependencyType === 'order_hint'), true);
});

await test('A orchestrator persists durable journal, resume context, and compensation plan', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-orchestration-'));
  try {
    const { coreFacade } = createAgRuntime({ auditRoot: dir });
    const task = coreFacade.createTask('엑셀 보고서 만들고 그리고 안내문 작성해', {
      createdAt: '2026-06-08T00:05:00.000Z'
    });
    const decision = createApprovalDecision({
      approvalId: task.approvalCard.approvalId,
      taskId: task.taskId,
      decision: ApprovalDecision.APPROVE,
      deviceId: 'journal_test',
      decidedAt: '2026-06-08T00:06:00.000Z'
    });
    coreFacade.submitApprovalDecision(decision);
    coreFacade.createCapabilityRequest(task.taskId, decision);
    const packet = coreFacade.createExecutionPacket(task.taskId, {
      approvalDecision: decision,
      capabilityToken: { tokenId: 'cap_journal_test' },
      userConfirmation: { confirmed: true }
    });
    assert.equal(packet.traceId, task.orchestrationTrace.traceId);

    const resume = coreFacade.resumeTask(task.taskId);
    assert.equal(resume.resumable, true);
    assert.equal(resume.pendingNodes.some((node) => node.nodeId.startsWith('action_') && node.status === 'ready'), true);

    const compensation = coreFacade.planCompensation(task.taskId, {
      failureBranchId: 'failure_dag_node_failed',
      evidence: { failedNodeId: 'action_2' }
    });
    assert.equal(compensation.success, true);
    assert.equal(compensation.actions.length >= 1, true);
    assert.equal(compensation.actions[0].recordType, 'orchestration_compensation');

    const journal = await readJsonl(join(dir, 'core-orchestration.jsonl'));
    assert.ok(journal.some((record) => record.recordType === 'orchestration_checkpoint' && record.reason === 'execution_packet_created'));
    assert.ok(journal.some((record) => record.recordType === 'orchestration_node' && record.status === 'ready'));
    assert.ok(journal.some((record) => record.recordType === 'orchestration_compensation'));
    assert.ok(journal.some((record) => record.recordType === 'orchestration_step' && record.phase === 'compensation.planned'));
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

await test('A CoreOrchestrationWorker runs approved tasks through E, B, G, and F', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-worker-'));
  try {
    await writeFile(join(dir, 'visible-note.txt'), 'worker fixture', 'utf8');
    const { coreFacade, orchestrationWorker, growthRuntime } = createAgRuntime({
      allowedRoots: [dir],
      auditRoot: dir,
      cwd: () => dir
    });
    const task = coreFacade.createTask('파일 목록 보여줘');
    const run = await orchestrationWorker.runTask(task.taskId, { deviceId: 'worker_test' });
    const storedTask = coreFacade.getTask(task.taskId);

    assert.equal(
      run.success,
      true,
      JSON.stringify(run.executionVerification?.checks?.filter((check) => check.status === 'failed') ?? [])
    );
    assert.equal(run.status, TaskStatus.COMPLETED);
    assert.equal(storedTask.status, TaskStatus.COMPLETED);
    assert.equal(run.capability.scope.allowedPaths[0], dir);
    assert.equal(run.packet.capabilityToken.capabilityToken, undefined);
    assert.equal(run.planVerification.status, 'passed');
    assert.equal(run.policyVerification.status, 'passed');
    assert.equal(run.execution.status, TaskStatus.COMPLETED);
    assert.equal(run.execution.executionResult.executedBy.module, ModuleId.PC_AGENT);
    assert.equal(run.executionVerification.status, 'passed');
    assert.equal(run.learning.ingest.success, true);
    assert.equal(growthRuntime.ingestor.all().some((event) => event.taskId === task.taskId), true);
    assert.equal(storedTask.orchestrationTrace.steps.some((step) => step.phase === 'worker.execution.completed'), true);
    assert.equal(storedTask.orchestrationTrace.steps.some((step) => step.phase === 'worker.learning.ingested'), true);

    const journal = await readJsonl(join(dir, 'core-orchestration.jsonl'));
    assert.equal(journal.some((record) => record.reason === 'worker_execution_started'), true);
    assert.equal(journal.some((record) => record.recordType === 'orchestration_node' && record.status === 'completed'), true);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

await test('A CoreOrchestrationWorker executes plan graph nodes with artifact bundles and partial compensation', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-worker-graph-'));
  try {
    const { coreFacade, policyRuntime, verificationRuntime, growthRuntime } = createAgRuntime({
      allowedRoots: [dir],
      auditRoot: dir,
      cwd: () => dir,
      env: {}
    });
    const receivedPackets = [];
    const fakePcAgent = {
      async receiveExecutionPacket(packet) {
        receivedPackets.push(packet);
        if (packet.planGraphNodeId === 'action_2') {
          return {
            taskId: packet.taskId,
            status: TaskStatus.BLOCKED,
            blockedReason: 'fixture-node-failed',
            executionResult: {
              status: 'blocked',
              summary: 'fixture-node-failed',
              outputPaths: [],
              changedItems: [],
              rollbackAvailable: false
            },
            memoryEvent: null
          };
        }
        // This scheduling fixture must satisfy the real predecessor G gate.
        // A fabricated B success with no file is now correctly rejected early.
        const startedAt = new Date().toISOString();
        const undoJournalId = `undo_${packet.planGraphNodeId}`;
        await writeFile(join(dir, `${packet.planGraphNodeId}.txt`), 'synthetic predecessor output');
        return {
          taskId: packet.taskId,
          status: TaskStatus.COMPLETED,
          executionResult: {
            taskId: packet.taskId,
            status: 'success',
            startedAt,
            finishedAt: startedAt,
            undoJournalId,
            safety: { capabilityTokenUsed: packet.capabilityToken.tokenId },
            summary: `${packet.planGraphNodeId} completed`,
            outputPaths: [join(dir, `${packet.planGraphNodeId}.txt`)],
            changedItems: [{ path: join(dir, `${packet.planGraphNodeId}.txt`), changeType: 'created' }],
            rollbackAvailable: true,
            executedBy: {
              module: ModuleId.PC_AGENT,
              toolName: packet.action.toolName
            },
            evidence: {
              verificationEvidenceId: `ev_${packet.planGraphNodeId}`,
              undoJournalId: `undo_${packet.planGraphNodeId}`
            }
          },
          evidence: { evidenceId: `ev_${packet.planGraphNodeId}`, taskId: packet.taskId, status: 'success',
            outputPaths: [join(dir, `${packet.planGraphNodeId}.txt`)], shadow: { expectedChangesCount: 1 }, undo: { undoJournalId } },
          memoryEvent: null
        };
      }
    };
    const graphWorker = new CoreOrchestrationWorker({
      coreFacade,
      policyRuntime,
      verificationRuntime,
      growthRuntime,
      pcAgent: fakePcAgent,
      allowedPaths: [dir]
    });
    const task = coreFacade.createTask('첫 파일 만들고 그리고 두번째 파일 만들고 그리고 세번째 파일 만들어');
    assert.equal(task.plan.planGraph.nodes.filter((node) => node.nodeId.startsWith('action_')).length >= 3, true);

    const run = await graphWorker.runTask(task.taskId, { deviceId: 'graph_worker_test' });
    const storedTask = coreFacade.getTask(task.taskId);
    const journal = await readJsonl(join(dir, 'core-orchestration.jsonl'));

    assert.equal(run.success, false);
    assert.equal(storedTask.status, TaskStatus.FAILED);
    assert.equal(run.planGraphRun.failedNodeId, 'action_2');
    assert.deepEqual(run.planGraphRun.skippedNodeIds, ['action_3']);
    assert.equal(run.planGraphRun.nodeRuns.find((node) => node.nodeId === 'action_1').status, 'completed');
    assert.equal(run.planGraphRun.nodeRuns.find((node) => node.nodeId === 'action_2').status, 'failed');
    assert.equal(run.planGraphRun.nodeRuns.find((node) => node.nodeId === 'action_3').status, 'skipped');
    assert.equal(run.planGraphRun.nodeRuns[0].artifactBundle.artifactVersion, 'a-plan-node-artifact-bundle-v1');
    assert.equal(run.planGraphRun.schedule.scheduleVersion, 'a-plan-parallel-dag-scheduler-v1');
    assert.equal(run.planGraphRun.nodeRuns[0].artifactBundle.scheduleWave, 1);
    assert.equal(run.planGraphRun.partialCompensation.mode, 'partial');
    assert.deepEqual(run.planGraphRun.partialCompensation.targetNodeIds, ['action_1']);
    assert.equal(run.planGraphRun.partialCompensation.actions.every((action) => action.targetNodeId === 'action_1'), true);
    assert.equal(run.planGraphRun.artifactExport.exportVersion, 'a-plan-node-artifact-export-v1');
    assert.equal(graphWorker.nodeArtifactRetentionStatus(task.taskId).retentionVersion, 'a-plan-node-artifact-retention-v1');
    assert.equal(graphWorker.compensationExecutionRunnerStatus(task.taskId).runnerVersion, 'a-plan-compensation-execution-runner-v1');
    const planGraphGate = graphWorker.runPlanGraphProductGate(task.taskId);
    assert.equal(planGraphGate.gateVersion, 'a-plan-graph-product-gate-v1');
    assert.equal(planGraphGate.status, 'passed');
    assert.equal(planGraphGate.releaseDossier.dossierVersion, 'a-plan-graph-release-dossier-v1');
    assert.equal(planGraphGate.releaseDossier.status, 'passed');
    assert.equal(planGraphGate.releaseDossier.artifactManifest.artifactManifestVersion, 'a-plan-graph-release-artifact-manifest-v1');
    assert.equal(planGraphGate.releaseDossier.artifactManifest.planGraphExecutionManifest.manifestVersion, 'a-plan-graph-execution-manifest-v1');
    assert.equal(planGraphGate.releaseDossier.artifactManifest.nodeArtifactManifest.manifestVersion, 'a-plan-node-artifact-release-manifest-v1');
    assert.equal(planGraphGate.releaseDossier.artifactManifest.compensationManifest.manifestVersion, 'a-plan-graph-compensation-release-manifest-v1');
    assert.equal(planGraphGate.releaseDossier.artifactManifest.rawPlanPayloadStored, false);
    assert.equal(planGraphGate.releaseDossier.artifactManifest.rawNodeArtifactPayloadStored, false);
    assert.equal(planGraphGate.releaseDossier.artifactManifest.rawOutputPathsStored, false);
    assert.equal(planGraphGate.releaseDossier.artifactManifest.rawCapabilityTokensStored, false);
    assert.equal(planGraphGate.releaseDossier.artifactManifest.rawLeakCheck.rawLeakDetected, false);
    assert.equal(planGraphGate.releaseDossier.ciNightlyGatePlan.planVersion, 'a-plan-graph-ci-nightly-gate-plan-v1');
    assert.equal(planGraphGate.releaseDossier.externalWormPromotionPackage.packageVersion, 'a-plan-graph-worm-promotion-package-v1');
    assert.equal(planGraphGate.releaseDossier.externalWormPromotionPackage.providerContractVersion, 'a-plan-graph-worm-provider-contract-v1');
    assert.equal(planGraphGate.releaseDossier.externalWormPromotionPackage.status, 'ready');
    assert.equal(planGraphGate.checks.some((check) => check.checkId === 'plan_graph_worm_promotion_package_ready' && check.status === 'passed'), true);
    assert.equal(planGraphGate.checks.some((check) => check.checkId === 'plan_graph_release_dossier_ready' && check.status === 'passed'), true);
    assert.equal(receivedPackets.map((packet) => packet.planGraphNodeId).join(','), 'action_1,action_2');
    assert.notEqual(receivedPackets[0].capabilityToken.tokenId, receivedPackets[1].capabilityToken.tokenId);
    assert.equal(journal.some((record) => record.recordType === 'orchestration_node' && record.nodeId === 'action_3' && record.status === 'skipped'), true);
    assert.equal(journal.some((record) => record.recordType === 'orchestration_step' && record.phase === 'compensation.partial.planned'), true);
    assert.equal(coreFacade.eventBus.recent(30).some((event) => event.eventType === 'worker.plan_node.skipped'), true);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

await test('A CoreOrchestrationWorker executes parallel-ready plan graph waves', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-worker-parallel-'));
  try {
    const { coreFacade, policyRuntime, verificationRuntime, growthRuntime } = createAgRuntime({
      allowedRoots: [dir],
      auditRoot: dir,
      cwd: () => dir,
      env: {}
    });
    const received = [];
    let inFlight = 0;
    let maxInFlight = 0;
    const fakePcAgent = {
      async receiveExecutionPacket(packet) {
        received.push(packet.planGraphNodeId);
        inFlight += 1;
        maxInFlight = Math.max(maxInFlight, inFlight);
        await new Promise((resolve) => setTimeout(resolve, 10));
        inFlight -= 1;
        const outputPath = join(dir, `${packet.planGraphNodeId}.txt`);
        const undoJournalId = `undo_${packet.planGraphNodeId}`;
        const startedAt = new Date().toISOString();
        await writeFile(outputPath, `${packet.planGraphNodeId} completed`, 'utf8');
        return {
          taskId: packet.taskId,
          status: TaskStatus.COMPLETED,
          executionResult: {
            taskId: packet.taskId,
            status: 'success',
            summary: `${packet.planGraphNodeId} completed`,
            startedAt,
            finishedAt: startedAt,
            outputPaths: [outputPath],
            changedItems: [{ path: outputPath, changeType: 'created' }],
            undoJournalId,
            rollbackAvailable: true,
            executedBy: {
              module: ModuleId.PC_AGENT,
              toolName: packet.action.toolName
            },
            safety: {
              capabilityTokenUsed: packet.capabilityToken.tokenId
            }
          },
          evidence: {
            evidenceId: `parallel_ev_${packet.planGraphNodeId}`,
            taskId: packet.taskId,
            status: 'success',
            outputPaths: [outputPath],
            shadow: { expectedChangesCount: 1 },
            undo: { undoJournalId }
          },
          memoryEvent: null
        };
      }
    };
    const graphWorker = new CoreOrchestrationWorker({
      coreFacade,
      policyRuntime,
      verificationRuntime,
      growthRuntime,
      pcAgent: fakePcAgent,
      allowedPaths: [dir],
      maxPlanParallelism: 3
    });
    const task = coreFacade.createTask('첫 파일 만들고 그리고 동시에 두번째 파일 만들고 그리고 동시에 세번째 파일 만들어');
    assert.equal(task.plan.planGraph.scheduler.mode, 'parallel_ready');
    assert.equal(task.plan.planGraph.scheduler.waves[0].parallelizable, true);

    const run = await graphWorker.runTask(task.taskId, { deviceId: 'parallel_graph_worker_test' });

    assert.equal(
      run.success,
      true,
      JSON.stringify(run.executionVerification?.checks?.filter((check) => check.status === 'failed') ?? [])
    );
    assert.equal(run.planGraphRun.schedule.waves[0].nodeIds.length >= 2, true);
    assert.equal(run.trustAuthorization?.allowed, true);
    assert.equal(
      run.planGraphRun.nodeRuns
        .filter((node) => node.status === 'completed')
        .every((node) => node.trustAuthorization?.allowed === true),
      true
    );
    assert.equal(maxInFlight > 1, true);
    assert.equal(received.length >= 3, true);
    assert.equal(run.planGraphRun.artifactExport.exportVersion, 'a-plan-node-artifact-export-v1');
    assert.equal(run.execution.executionResult.evidence.nodeArtifactBundles.filter((bundle) => bundle.status === 'completed').length >= 3, true);
    const parallelGraphGate = graphWorker.runPlanGraphProductGate(task.taskId);
    assert.equal(parallelGraphGate.status, 'passed');
    assert.equal(parallelGraphGate.releaseDossier.dossierVersion, 'a-plan-graph-release-dossier-v1');
    assert.equal(parallelGraphGate.releaseDossier.artifacts.byStatus.completed >= 3, true);
    assert.equal(parallelGraphGate.releaseDossier.schedule.parallelWaveCount >= 1, true);
    assert.equal(parallelGraphGate.releaseDossier.artifactManifest.artifactManifestVersion, 'a-plan-graph-release-artifact-manifest-v1');
    assert.equal(parallelGraphGate.releaseDossier.externalWormPromotionPackage.packageVersion, 'a-plan-graph-worm-promotion-package-v1');
    assert.equal(parallelGraphGate.releaseDossier.externalWormPromotionPackage.status, 'ready');
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

await test('A CoreOrchestrationWorker drains queued tasks with lock and retry metadata', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-worker-queue-'));
  try {
    await writeFile(join(dir, 'queue-visible-note.txt'), 'worker queue fixture', 'utf8');
    const { coreFacade, orchestrationWorker } = createAgRuntime({
      allowedRoots: [dir],
      auditRoot: dir,
      cwd: () => dir,
      workerBaseBackoffMs: 5
    });

    const task = coreFacade.createTask('파일 목록 보여줘');
    const queued = orchestrationWorker.enqueueTask(task.taskId, { userConfirmation: { confirmed: true } });
    assert.equal(queued.status, 'queued');
    const drained = await orchestrationWorker.drain({ limit: 1 });
    assert.equal(drained.processed, 1);
    assert.equal(drained.results[0].item.status, 'succeeded');
    assert.equal(coreFacade.getTask(task.taskId).status, TaskStatus.COMPLETED);

    const lockedTask = coreFacade.createTask('파일 목록 보여줘');
    const lockedQueued = orchestrationWorker.enqueueTask(lockedTask.taskId, { userConfirmation: { confirmed: true } });
    orchestrationWorker.activeTaskIds.add(lockedTask.taskId);
    const locked = await orchestrationWorker.runNext();
    assert.equal(locked.locked, true);
    assert.equal(locked.item.status, 'retry_scheduled');
    assert.equal(locked.item.lastError, 'task-locked');
    orchestrationWorker.activeTaskIds.delete(lockedTask.taskId);
    orchestrationWorker.queue.find((item) => item.queueId === lockedQueued.queueId).nextAttemptAt = '2000-01-01T00:00:00.000Z';
    const retried = await orchestrationWorker.drain({ limit: 1, now: '2030-01-01T00:00:00.000Z' });
    assert.equal(retried.results[0].item.status, 'succeeded');
    assert.equal(coreFacade.getTask(lockedTask.taskId).status, TaskStatus.COMPLETED);
    assert.equal(orchestrationWorker.queueStatus().counts.succeeded, 2);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

