await test('A Core service runtime entry starts full A-G worker daemon', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-core-service-runtime-'));
  let service = null;
  try {
    const workspaceRoot = join(dir, 'workspace');
    const auditRoot = join(dir, 'logs');
    const workerLeaseStorePath = join(dir, 'runtime', 'worker-leases.json');
    const workerQueueStorePath = join(dir, 'runtime', 'worker-queue.json');
    await mkdir(workspaceRoot, { recursive: true });
    await writeFile(join(workspaceRoot, 'service-runtime-visible-note.txt'), 'service runtime fixture', 'utf8');
    service = await startCoreServiceRuntime({
      env: {
        ...process.env,
        PORT: '0',
        JARVIS_CORE_HOST: '127.0.0.1',
        JARVIS_CORE_ADMIN_TOKEN: 'service-runtime-token',
        JARVIS_CORE_ALLOWED_ROOTS: workspaceRoot,
        JARVIS_CORE_AUDIT_ROOT: auditRoot,
        JARVIS_CORE_EVENT_LOG: join(auditRoot, 'core-events.jsonl'),
        JARVIS_CORE_ORCHESTRATION_JOURNAL: join(auditRoot, 'core-orchestration.jsonl'),
        JARVIS_CORE_WORKER_LEASE_STORE: workerLeaseStorePath,
        JARVIS_CORE_WORKER_QUEUE_STORE: workerQueueStorePath,
        JARVIS_CORE_WORKER_DAEMON_AUTOSTART: 'true',
        JARVIS_CORE_WORKER_DAEMON_INTERVAL_MS: '20',
        JARVIS_CORE_WORKER_DAEMON_DRAIN_LIMIT: '1'
      }
    });

    assert.equal(service.options.serviceRuntimeVersion, 'a-core-service-runtime-entry-v1');
    assert.equal(service.daemonStart.status, 'started');
    assert.equal(service.workerDaemon.status().running, true);
    const health = await getJson(`${service.baseUrl}/health`);
    assert.equal(health.module, ModuleId.CORE);
    const diagnostics = await getJson(`${service.baseUrl}/admin/diagnostics`, 'service-runtime-token');
    assert.equal(diagnostics.workerDaemon.daemonVersion, 'a-core-worker-daemon-v1');
    assert.equal(diagnostics.adminAuth.authVersion, 'a-core-admin-auth-v1');

    const created = await postJson(`${service.baseUrl}/tasks`, { rawText: '파일 목록 보여줘' });
    await postJson(`${service.baseUrl}/tasks/${created.taskId}/queue`, {
      options: { userConfirmation: { confirmed: true }, timeoutMs: 10_000 }
    });

    let detail = null;
    for (let attempt = 0; attempt < 50; attempt += 1) {
      detail = await getJson(`${service.baseUrl}/tasks/${created.taskId}`, 'service-runtime-token');
      if (detail.status === TaskStatus.COMPLETED) break;
      await new Promise((resolveDelay) => setTimeout(resolveDelay, 20));
    }
    assert.equal(detail.status, TaskStatus.COMPLETED);
    assert.equal(detail.executionVerification.status, 'passed');
    assert.equal(detail.learningResult.ingest.success, true);
    assert.equal(service.workerDaemon.status().processedTotal >= 1, true);
    assert.equal(await pathExists(workerQueueStorePath), true);
    assert.equal(await pathExists(workerLeaseStorePath), true);
    const events = await readJsonl(join(auditRoot, 'core-events.jsonl'));
    assert.equal(events.some((event) => event.eventType === 'core.worker.daemon.started'), true);
    assert.equal(events.some((event) => event.eventType === 'core.worker.daemon.tick.succeeded'), true);
  } finally {
    service?.workerDaemon?.stop?.({ reason: 'service-runtime-entry-test' });
    if (service?.server?.listening) {
      await new Promise((resolveClose) => service.server.close(resolveClose));
    }
    await rm(dir, { recursive: true, force: true });
  }
});

