await test('A EventBus persists events, replays durable log, tracks ack, and dead-letters failed subscribers', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-eventbus-'));
  try {
    const eventLogPath = join(dir, 'events.jsonl');
    const deliveryLogPath = join(dir, 'events-delivery.jsonl');
    const bus = new EventBus({ eventLogPath, deliveryLogPath });
    const delivered = [];
    bus.subscribe('task.plan.created', (event, delivery) => {
      delivered.push(event.eventId);
      delivery.ack();
    }, { subscriberId: 'planner_projection', requireAck: true });
    bus.subscribe('task.plan.created', () => {
      throw new Error('projection write failed');
    }, { subscriberId: 'broken_projection' });

    const first = bus.publish('task.plan.created', { taskId: 'task_event_1' });
    const second = bus.publish('task.plan.created', { taskId: 'task_event_2' });
    assert.equal(first.sequence, 1);
    assert.equal(second.sequence, 2);
    assert.deepEqual(delivered, ['evt_1', 'evt_2']);
    assert.equal(bus.deliveryStatus().pendingAcks.length, 0);
    assert.equal(bus.deliveryStatus().deadLetters.length, 2);

    const restarted = new EventBus({ eventLogPath, deliveryLogPath });
    assert.equal(restarted.recent(2)[0].eventId, 'evt_2');
    assert.deepEqual(restarted.replay({ eventType: 'task.plan.created', sinceEventId: 'evt_1', oldestFirst: true }).map((event) => event.eventId), ['evt_2']);
    restarted.subscribe('task.plan.created', (event, delivery) => delivery.ack(), {
      subscriberId: 'late_projection',
      requireAck: true,
      replayFrom: 'evt_1'
    });
    assert.equal(restarted.deliveryStatus().pendingAcks.length, 0);

    const deliveryRecords = await readJsonl(deliveryLogPath);
    assert.ok(deliveryRecords.some((record) => record.status === 'acked' && record.subscriberId === 'planner_projection'));
    assert.ok(deliveryRecords.some((record) => record.status === 'failed' && record.subscriberId === 'broken_projection'));
    assert.ok((await readJsonl(eventLogPath)).every((event) => event.durable === true));
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

await test('A EventBus replays a bounded tail from oversized durable logs', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-eventbus-tail-'));
  try {
    const eventLogPath = join(dir, 'events.jsonl');
    const lines = [];
    for (let index = 1; index <= 20; index += 1) {
      lines.push(JSON.stringify({
        eventId: `evt_${index}`,
        sequence: index,
        eventType: 'task.plan.created',
        source: 'A_CORE',
        payload: { taskId: `task_${index}`, padding: 'x'.repeat(80) },
        durable: true,
        createdAt: new Date(2026, 0, index).toISOString()
      }));
    }
    await writeFile(eventLogPath, `${lines.join('\n')}\n`, 'utf8');

    const restarted = new EventBus({
      eventLogPath,
      eventReplayMaxBytes: 1_000,
      eventReplayMaxRecords: 3
    });
    assert.deepEqual(restarted.recent(3).map((event) => event.eventId), ['evt_20', 'evt_19', 'evt_18']);
    assert.equal(restarted.sequence, 20);
    assert.equal(restarted.eventReplayStatus.truncated, true);
    assert.equal(restarted.eventReplayStatus.loadedCount, 3);
    const next = restarted.publish('task.plan.created', { taskId: 'task_21' });
    assert.equal(next.eventId, 'evt_21');
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

await test('A EventBus redrives pending ack and dead-letter projection recovery', () => {
  const bus = new EventBus();
  let ackProjection = false;
  bus.subscribe('projection.updated', (_event, delivery) => {
    if (ackProjection) delivery.ack();
  }, {
    subscriberId: 'projection_ack',
    requireAck: true
  });
  bus.publish('projection.updated', { version: 1 });
  assert.equal(bus.deliveryStatus().pendingAcks.length, 1);
  ackProjection = true;
  const pendingRecovery = bus.redrivePendingAcks();
  assert.equal(pendingRecovery.redriven, 1);
  assert.equal(pendingRecovery.remainingPendingAcks, 0);

  let failProjection = true;
  bus.subscribe('projection.failed', (_event, delivery) => {
    if (failProjection) throw new Error('projection temporarily down');
    delivery.ack();
  }, {
    subscriberId: 'projection_flaky',
    requireAck: true
  });
  bus.publish('projection.failed', { version: 2 });
  assert.equal(bus.deliveryStatus().deadLetters.length, 1);
  failProjection = false;
  const deadLetterRecovery = bus.redriveDeadLetters({ subscriberId: 'projection_flaky' });
  assert.equal(deadLetterRecovery.redriven, 1);
  assert.equal(deadLetterRecovery.remainingDeadLetters, 0);
  assert.equal(bus.deliveryStatus().deliveryRecords.some((record) => record.redriveType === 'pending_ack'), true);
  assert.equal(bus.deliveryStatus().deliveryRecords.some((record) => record.redriveType === 'dead_letter' && record.status === 'recovered'), true);

  const projectionRecovery = bus.projectionRecovery();
  assert.equal(projectionRecovery.pending.remainingPendingAcks, 0);
  assert.equal(projectionRecovery.deadLetters.remainingDeadLetters, 0);
});

await test('A EventBus enforces topic backpressure and recovers projection leases', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-event-bus-product-'));
  try {
    const broker = new InMemoryEventBrokerAdapter({ adapterName: 'test-external-broker' });
    const projectionLeasePath = join(dir, 'projection-leases.jsonl');
    const bus = new EventBus({ brokerAdapter: broker, projectionLeasePath });
    const policy = bus.configureTopicPolicy('projection.saturated', {
      maxPendingAcks: 1,
      maxRecentEvents: 2,
      overflow: 'reject'
    });
    bus.configureTopicPolicy('projection.retry', {
      maxPendingAcks: 1,
      overflow: 'retry'
    });
    assert.equal(policy.policyVersion, 'a-event-topic-backpressure-policy-v1');
    bus.subscribe('projection.saturated', () => {}, {
      subscriberId: 'slow_projection',
      requireAck: true
    });
    const first = bus.publish('projection.saturated', { version: 1 });
    const rejected = bus.publish('projection.saturated', { version: 2 });
    assert.equal(first.eventId, 'evt_1');
    assert.equal(rejected.recordVersion, 'a-event-backpressure-record-v1');
    assert.equal(rejected.status, 'backpressure_rejected');
    assert.equal(bus.externalBrokerStatus().adapterVersion, 'a-event-external-broker-adapter-contract-v1');
    assert.equal(bus.externalBrokerStatus().deliveries.some((delivery) => delivery.status === 'published'), true);
    assert.equal(bus.deliveryStatus().backpressure.records.length, 1);
    assert.equal(bus.deliveryStatus().backpressure.overflowDashboard.dashboardVersion, 'a-event-overflow-policy-dashboard-v1');
    assert.equal(bus.deliveryStatus().backpressure.pressureByTopic.some((item) => item.eventType === 'projection.saturated' && item.pendingAckCount === 1), true);
    assert.equal(bus.ack(first.eventId, 'slow_projection').acked, true);
    const second = bus.publish('projection.saturated', { version: 3 });
    assert.equal(bus.ack(second.eventId, 'slow_projection').acked, true);
    const third = bus.publish('projection.saturated', { version: 4 });
    assert.equal(second.eventId, 'evt_2');
    assert.equal(third.eventId, 'evt_3');
    assert.equal(bus.replay({ eventType: 'projection.saturated', limit: 10 }).length, 2);

    const lease = bus.acquireProjectionLease('D.bridge_projection', {
      ownerId: 'bridge-projection-worker',
      ttlMs: 10,
      now: '2026-06-21T00:00:00.000Z'
    });
    assert.equal(lease.acquired, true);
    assert.equal(lease.lease.leaseVersion, 'a-event-projection-lease-v1');
    assert.equal(bus.projectionLeaseBackendStatus().backendVersion, 'a-event-projection-lease-file-backend-v1');
    const restarted = new EventBus({ projectionLeasePath });
    assert.equal(restarted.projectionLeaseStatus({ now: '2026-06-21T00:00:00.005Z' }).activeLeaseCount, 1);
    const recovery = bus.recoverProjectionLeases({ now: '2026-06-21T00:00:00.100Z' });
    assert.equal(recovery.recoveryVersion, 'a-event-projection-lease-recovery-v1');
    assert.equal(recovery.recoveredCount, 1);
    assert.equal(bus.deliveryStatus().projectionLeases.activeLeaseCount, 0);
    const productGate = bus.operationalProductGate();
    assert.equal(productGate.productGateVersion, 'a-event-bus-operational-product-gate-v1');
    assert.equal(productGate.status, 'passed');
    assert.equal(productGate.releaseDossier.dossierVersion, 'a-event-bus-operational-release-dossier-v1');
    assert.equal(productGate.releaseDossier.status, 'passed');
    assert.equal(productGate.releaseDossier.artifactManifest.artifactManifestVersion, 'a-event-bus-operational-release-artifact-manifest-v1');
    assert.equal(productGate.releaseDossier.artifactManifest.brokerContractManifest.manifestVersion, 'a-event-broker-provider-contract-manifest-v1');
    assert.equal(productGate.releaseDossier.artifactManifest.projectionLeaseManifest.manifestVersion, 'a-event-projection-lease-operational-manifest-v1');
    assert.equal(productGate.releaseDossier.artifactManifest.rawEventPayloadStored, false);
    assert.equal(productGate.releaseDossier.artifactManifest.rawBrokerPayloadStored, false);
    assert.equal(productGate.releaseDossier.artifactManifest.rawDeliveryLogPathStored, false);
    assert.equal(productGate.releaseDossier.artifactManifest.rawProjectionLeasePathStored, false);
    assert.equal(productGate.releaseDossier.artifactManifest.rawLeakCheck.rawLeakDetected, false);
    assert.equal(productGate.releaseDossier.ciNightlyGatePlan.planVersion, 'a-event-bus-operational-ci-nightly-gate-plan-v1');
    assert.equal(productGate.releaseDossier.externalWormPromotionPackage.packageVersion, 'a-event-bus-operational-worm-promotion-package-v1');
    assert.equal(productGate.releaseDossier.externalWormPromotionPackage.providerContractVersion, 'a-event-bus-operational-worm-provider-contract-v1');
    assert.equal(productGate.releaseDossier.externalWormPromotionPackage.status, 'ready');
    assert.equal(productGate.checks.some((check) => check.checkId === 'event_external_broker_delivery_observed' && check.passed), true);
    assert.equal(productGate.checks.some((check) => check.checkId === 'event_bus_operational_worm_promotion_package_ready' && check.passed), true);
    assert.equal(productGate.checks.some((check) => check.checkId === 'event_bus_operational_release_dossier_ready' && check.passed), true);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

