await test('A Core HTTP API runs approved tasks through the orchestration worker endpoint', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-worker-http-'));
  try {
    await writeFile(join(dir, 'api-visible-note.txt'), 'worker http fixture', 'utf8');
    const runtime = createAgRuntime({ allowedRoots: [dir], auditRoot: dir, cwd: () => dir });
    await withServer(
      createCoreServer(runtime.coreFacade, {
        adminToken: 'test-admin-token',
        orchestrationWorker: runtime.orchestrationWorker
      }),
      async (baseUrl) => {
        const created = await postJson(`${baseUrl}/tasks`, { rawText: '파일 목록 보여줘' });
        const openApi = await getJson(`${baseUrl}/openapi.json`);
        assert.equal(openApi.paths['/worker/queue/drain'].post.operationId, 'drainCoreWorkerQueue');
        assert.equal(openApi.paths['/worker/leases'].get.operationId, 'getCoreWorkerLeases');
        assert.equal(openApi.paths['/worker/daemon'].get.operationId, 'getCoreWorkerDaemon');
        assert.equal(openApi.paths['/tasks/{taskId}/compensation/plan'].get.operationId, 'previewCoreCompensationReplay');
        const leases = await getJson(`${baseUrl}/worker/leases`);
        assert.equal(leases.leaseTableVersion, 'a-worker-lease-table-v1');
        const rejectedDaemonStatus = await getJson(`${baseUrl}/worker/daemon`);
        assert.equal(rejectedDaemonStatus.error.code, 'A_ADMIN_TOKEN_REQUIRED');
        const daemonStatus = await getJson(`${baseUrl}/worker/daemon`, 'test-admin-token');
        assert.equal(daemonStatus.daemonVersion, 'a-core-worker-daemon-v1');
        const run = await postJson(`${baseUrl}/tasks/${created.taskId}/run`, {
          decision: ApprovalDecision.APPROVE,
          userConfirmation: { confirmed: true }
        });
        const detail = await getJson(`${baseUrl}/tasks/${created.taskId}`, 'test-admin-token');

        assert.equal(run.success, true);
        assert.equal(run.status, TaskStatus.COMPLETED);
        assert.equal(run.executionVerification.status, 'passed');
        assert.equal(detail.status, TaskStatus.COMPLETED);
        assert.equal(detail.executionVerification.status, 'passed');
        assert.equal(detail.learningResult.ingest.success, true);

        const queuedTask = await postJson(`${baseUrl}/tasks`, { rawText: '파일 목록 보여줘' });
        const queued = await postJson(`${baseUrl}/tasks/${queuedTask.taskId}/queue`, {
          options: { userConfirmation: { confirmed: true }, baseBackoffMs: 5 }
        });
        assert.equal(queued.status, 'queued');
        const queueStatus = await getJson(`${baseUrl}/worker/queue`);
        assert.equal(queueStatus.total >= 1, true);
        const drained = await postJson(`${baseUrl}/worker/queue/drain`, { limit: 1 });
        assert.equal(drained.processed, 1);
        assert.equal(drained.results[0].item.status, 'succeeded');

        const daemonTask = await postJson(`${baseUrl}/tasks`, { rawText: '파일 목록 보여줘' });
        await postJson(`${baseUrl}/tasks/${daemonTask.taskId}/queue`, {
          options: { userConfirmation: { confirmed: true } }
        });
        const rejectedDaemonTick = await postJson(`${baseUrl}/worker/daemon/tick`, { reason: 'http-worker-daemon', drainLimit: 1 });
        assert.equal(rejectedDaemonTick.error.code, 'A_ADMIN_TOKEN_REQUIRED');
        const daemonTick = await postJson(`${baseUrl}/worker/daemon/tick`, { reason: 'http-worker-daemon', drainLimit: 1 }, 'test-admin-token');
        assert.equal(daemonTick.drain.processed, 1);
        assert.equal(daemonTick.daemon.daemonVersion, 'a-core-worker-daemon-v1');
      }
    );
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

