await test('A CoreClient drives task APIs and detects OpenAPI contract drift', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-core-client-'));
  try {
    await writeFile(join(dir, 'client-visible-note.txt'), 'core client fixture', 'utf8');
    const runtime = createAgRuntime({ allowedRoots: [dir], auditRoot: dir, cwd: () => dir });
    await withServer(
      createCoreServer(runtime.coreFacade, {
        adminToken: 'client-admin-token',
        orchestrationWorker: runtime.orchestrationWorker
      }),
      async (baseUrl) => {
        const client = new CoreClient({ baseUrl, adminToken: 'client-admin-token' });
        assert.equal((await client.health()).module, ModuleId.CORE);
        const openApi = await client.openApi();
        const snapshot = createCoreApiContractSnapshot(openApi, {
          label: 'client-baseline',
          generatedAt: '2026-06-21T00:00:00.000Z'
        });
        assert.equal(snapshot.snapshotVersion, 'a-core-api-contract-snapshot-v1');
        assert.equal(snapshot.operations.some((operation) => operation.operationId === 'runCoreCompensationReplay'), true);
        assert.equal(snapshot.operations.some((operation) => operation.operationId === 'tickCoreWorkerDaemon'), true);
        assert.equal(snapshot.digest.startsWith('sha256:'), true);

        const driftedOpenApi = structuredClone(openApi);
        delete driftedOpenApi.paths['/tasks/{taskId}/run'];
        const driftedSnapshot = createCoreApiContractSnapshot(driftedOpenApi, {
          label: 'client-drifted',
          generatedAt: '2026-06-21T00:01:00.000Z'
        });
        const diff = diffCoreApiContractSnapshots(snapshot, driftedSnapshot);
        assert.equal(diff.diffVersion, 'a-core-api-contract-diff-v1');
        assert.equal(diff.status, 'breaking-change');
        assert.equal(diff.removedPaths.includes('/tasks/{taskId}/run'), true);

        const task = await client.createTask('파일 목록 보여줘');
        assert.equal(task.status, TaskStatus.WAITING_APPROVAL);
        const run = await client.runTask(task.taskId, {
          decision: ApprovalDecision.APPROVE,
          userConfirmation: { confirmed: true }
        });
        assert.equal(run.success, true);
        assert.equal((await client.getTask(task.taskId)).status, TaskStatus.COMPLETED);
        assert.equal((await client.workerLeases()).leaseTableVersion, 'a-worker-lease-table-v1');
        assert.equal((await client.workerDaemon()).daemonVersion, 'a-core-worker-daemon-v1');
        const daemonTask = await client.createTask('파일 목록 보여줘');
        await client.enqueueTask(daemonTask.taskId, { userConfirmation: { confirmed: true } });
        const daemonTick = await client.tickWorkerDaemon({ reason: 'client-daemon-tick', drainLimit: 1 });
        assert.equal(daemonTick.drain.processed, 1);
        const servicePlan = await client.createServicePlan({
          action: 'status',
          osPlatform: 'win32',
          isAdministrator: true,
          logs: { adminTokenHash: '0123456789abcdef0123456789abcdef0123456789abcdef0123456789abcdef' }
        });
        assert.equal(servicePlan.plan.planVersion, 'a-core-service-lifecycle-plan-v1');
        const diagnostics = await client.adminDiagnostics();
        assert.equal(diagnostics.core.taskCount >= 1, true);
        assert.equal(diagnostics.workerDaemon.daemonVersion, 'a-core-worker-daemon-v1');
      }
    );
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

await test('A Core contract gate blocks breaking OpenAPI drift until explicitly approved', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-a-core-contract-gate-'));
  try {
    const baselinePath = join(dir, 'core-openapi-snapshot.json');
    const runtime = createAgRuntime({ allowedRoots: [dir], auditRoot: dir, cwd: () => dir });
    const openApi = createCoreOpenApiSpec(runtime.coreFacade);
    const baseline = createCoreApiContractSnapshot(openApi, {
      label: 'gate-baseline',
      generatedAt: '2026-06-21T00:00:00.000Z'
    });
    await writeCoreContractSnapshot(baselinePath, baseline);
    const loaded = await loadCoreContractSnapshot(baselinePath);
    assert.equal(loaded.snapshotVersion, 'a-core-api-contract-snapshot-v1');

    const compatible = createCoreContractGateReport({
      baselineSnapshot: loaded,
      currentOpenApi: openApi,
      generatedAt: '2026-06-21T00:01:00.000Z'
    });
    assert.equal(compatible.gateVersion, 'a-core-contract-gate-v1');
    assert.equal(compatible.status, 'passed');
    assert.equal(compatible.gatePassed, true);

    const driftedOpenApi = structuredClone(openApi);
    delete driftedOpenApi.paths['/worker/daemon/tick'];
    const breaking = createCoreContractGateReport({
      baselineSnapshot: loaded,
      currentOpenApi: driftedOpenApi,
      generatedAt: '2026-06-21T00:02:00.000Z'
    });
    assert.equal(breaking.status, 'failed');
    assert.equal(breaking.gatePassed, false);
    assert.equal(breaking.requiredAction, 'approve-contract-diff');
    assert.equal(breaking.diff.removedPaths.includes('/worker/daemon/tick'), true);

    const approved = createCoreContractGateReport({
      baselineSnapshot: loaded,
      currentOpenApi: driftedOpenApi,
      generatedAt: '2026-06-21T00:03:00.000Z',
      allowBreaking: true
    });
    assert.equal(approved.status, 'passed');
    assert.equal(approved.gatePassed, true);
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

