  assert.equal(clarificationProductGate.checks.some((check) => check.checkId === 'clarification_ux_telemetry_passed' && check.passed), true);
  assert.equal(clarificationProductGate.checks.some((check) => check.checkId === 'clarification_operational_handoff_ready' && check.passed), true);
  assert.equal(clarificationProductGate.checks.some((check) => check.checkId === 'clarification_worm_promotion_package_ready' && check.passed), true);
