  assert.equal(autonomyReleaseDossier.liveWorkflow.workflowVersion, 'e-autonomy-release-live-workflow-v1');
  assert.equal(autonomyReleaseDossier.reviewerIdentity.identityContractVersion, 'e-autonomy-reviewer-identity-contract-v1');
  assert.equal(autonomyReleaseDossier.artifactManifest.rawCandidateStored, false);
  assert.equal(autonomyReleaseDossier.artifactManifest.rawLeakCheck.rawLeakDetected, false);
  assert.equal(autonomyReleaseDossier.operationalHandoffManifest.status, 'ready');
  assert.equal(autonomyReleaseDossier.ciNightlyGatePlan.planVersion, 'e-autonomy-ci-nightly-gate-plan-v1');
  assert.equal(autonomyReleaseDossier.externalWormPromotionPackage.packageVersion, 'e-autonomy-worm-promotion-package-v1');
  assert.equal(autonomyReleaseDossier.externalWormPromotionPackage.providerContractVersion, 'e-autonomy-worm-provider-contract-v1');
  assert.equal(autonomyReleaseDossier.checks.some((check) => check.checkId === 'autonomy_worm_promotion_package_ready' && check.passed), true);
  assert.equal(autonomyReleaseDossier.checks.every((check) => check.passed), true);

  const auditSummary = policyRuntime.auditSummary({ category: 'security' });
  assert.equal(auditSummary.module, ModuleId.POLICY_SECURITY);
  assert.equal(auditSummary.chain.valid, true);
  assert.equal(auditSummary.byCategory.security > 0, true);
  const auditReleaseDossier = policyRuntime.auditApiReleaseDossier({ reason: 'unit_security_audit_release' });
