  assert.match(runtimePolicyGate.releaseDossier.releaseHash, /^[a-f0-9]{64}$/);
  assert.equal(runtimePolicyGate.checks.some((check) => check.checkId === 'policy_ci_approval_artifact_signed' && check.passed), true);
  assert.equal(runtimePolicyGate.checks.some((check) => check.checkId === 'policy_as_code_release_dossier_ready' && check.passed), true);
  const standalonePolicyAnnotation = policyRuntime.policyAsCodeCiAnnotation();
  assert.equal(standalonePolicyAnnotation.annotationVersion, 'e-policy-as-code-ci-annotation-v1');
  const standalonePolicyArtifact = policyRuntime.policyAsCodeCiApprovalArtifact({ annotation: standalonePolicyAnnotation });
  assert.equal(standalonePolicyArtifact.artifactVersion, 'e-policy-as-code-ci-approval-artifact-v1');
  assert.equal(standalonePolicyArtifact.status, 'passed');
