      fixturePath,
      cycles: 2,
      jsonPath: join(dir, 'browser-replay-soak-report.json'),
      markdownPath: join(dir, 'browser-replay-soak-report.md'),
      csvPath: join(dir, 'browser-replay-soak-report.csv'),
