    assert.ok((await readFile(report.artifacts.csvPath, 'utf8')).includes('browser_replay_worm_promotion_package_ready'));
    assert.equal(JSON.parse(await readFile(report.artifacts.jsonPath, 'utf8')).productGate.status, 'passed');
