    assert.equal(dossier.externalWormPromotionPackage.packageVersion, 'b-workbook-worm-promotion-package-v1');
    assert.equal(dossier.externalWormPromotionPackage.providerContractVersion, 'b-workbook-worm-provider-contract-v1');
    assert.equal(dossier.externalWormPromotionPackage.status, 'ready');
    assert.equal(dossier.productGate.productGateVersion, 'b-workbook-product-gate-v1');
