await test('C/D wearable HUD adapter compresses voice, approval, and bridge state for monochrome glasses', () => {
  const adapter = new WearableHudAdapter({ bridgeUrl: 'http://127.0.0.1:17777' });
  const voiceIntent = adapter.parseVoice('자비스 승인 token=abc123 C:\\Users\\user\\secret.txt');
  assert.equal(voiceIntent.activationDetected, true);
  assert.equal(voiceIntent.intentName, 'approve');
  assert.equal(voiceIntent.privacy.rawTranscriptStored, false);
  assert.equal(voiceIntent.privacy.redactionTypes.includes('token'), true);
  assert.equal(voiceIntent.redactedPreview.includes('abc123'), false);

  const approvalState = createWearableApprovalState({
    card: {
      approvalId: 'appr_wearable_1',
      taskId: 'task_wearable_1',
      riskTier: 3,
      summary: 'C:\\Users\\user\\secret\\contract.xlsx 파일 이동 승인'
    },
    safety: {
      requiresPcConfirmation: true,
      affectedItemCount: 12,
      rollbackAvailable: true
    },
    session: {
      locked: false
    }
  });
  assert.equal(approvalState.actions.approve.enabled, false);
  assert.equal(approvalState.actions.pcHandoff.enabled, true);

  const frame = adapter.createFrame({
    mode: 'approval',
    connection: { connected: true },
    approval: approvalState,
    voiceIntent
  });
  assert.equal(frame.display.palette, 'monochrome-green');
  assert.equal(frame.lines.length <= frame.limits.maxLines, true);
  assert.equal(frame.lines.every((line) => line.text.length <= frame.limits.maxCharsPerLine), true);
  assert.equal(frame.lines.some((line) => line.text.includes('PC 확인 필요')), true);
  assert.equal(frame.layoutContract.operatorFirst, true);
  assert.equal(frame.layoutContract.hidesImplementationModules, true);
  assert.equal(frame.actions.some((item) => item.label.includes('PC 확인')), true);
  assert.equal(frame.context.some(([label, value]) => label === '허용' && value.includes('PC 확인 필요')), true);
  assert.equal(renderWearableHudText(frame).includes('JARVIS-WEARABLE-HUD'), true);

  const bridgeSyncPlan = createWearableBridgeSyncPlan({ taskId: 'task_wearable_1', eventCursor: 'evt_1' });
  assert.equal(bridgeSyncPlan.endpoints.some((item) => item.path === '/approvals'), true);
  assert.equal(bridgeSyncPlan.privacy.rawBridgeTokenStored, false);

  const html = renderWearableHudHtml(frame);
  assert.equal(html.includes('jarvis-wearable-hud-root'), true);
  assert.equal(html.includes('#00ff66'), true);
  assert.equal(html.includes('웨어러블 관제'), true);
  assert.equal(html.includes('Bearer '), false);
  assert.equal(html.includes('secret\\contract'), false);

  const productGate = createWearableHudProductGate({
    frame,
    voiceIntent,
    approvalState,
    bridgeSyncPlan,
    html
  });
  const releaseDossier = createWearableHudReleaseDossier({
    frame,
    voiceIntent,
    approvalState,
    bridgeSyncPlan,
    checks: productGate.checks
  });
  assert.equal(productGate.status, 'passed');
  assert.equal(releaseDossier.status, 'passed');
  assert.equal(releaseDossier.dossierSha256.length, 64);
});

