await test('C/D wearable browser client snapshots live bridge data without retaining secrets', async () => {
  const config = createWearableHudBrowserConfig({ bridgeUrl: 'http://bridge.local:17777' });
  const fetchImpl = async (url) => {
    if (url.endsWith('/health')) {
      return jsonResponse({ module: 'D_BRIDGE', status: 'ok' });
    }
    if (url.endsWith('/approvals')) {
      return jsonResponse({
        items: [{
          approvalId: 'appr_browser_1',
          taskId: 'task_browser_1',
          riskTier: 3,
          summary: 'C:\\Users\\user\\secret\\contract.xlsx token=hidden 이동 승인'
        }]
      });
    }
    if (url.includes('/events?eventType=task.status.changed')) {
      return jsonResponse({ items: [{ eventId: 'evt_1' }] });
    }
    if (url.endsWith('/tasks')) {
      return jsonResponse({ items: [{ taskId: 'task_browser_1', status: 'WAITING_APPROVAL', title: '계약 파일 이동' }] });
    }
    return jsonResponse({}, { status: 404, ok: false });
  };

  const snapshot = await createWearableHudBrowserSnapshot({
    config,
    fetchImpl,
    tokenProvider: () => 'field-token'
  });
  assert.equal(wearableHudBrowserClientVersion, 'c-d-wearable-hud-browser-client-v1');
  assert.equal(snapshot.status, 'synced');
  assert.equal(snapshot.frame.display.palette, 'monochrome-green');
  assert.equal(snapshot.frame.lines.every((line) => line.text.length <= snapshot.frame.limits.maxCharsPerLine), true);
  assert.equal(JSON.stringify(snapshot).includes('field-token'), false);
  assert.equal(JSON.stringify(snapshot).includes('hidden'), false);
  assert.equal(snapshot.currentApproval.actions.approve.enabled, false);
  assert.equal(snapshot.currentApproval.actions.pcHandoff.enabled, true);

  const intent = createWearableBrowserVoiceIntent({ transcript: '자비스 승인 token=hidden' });
  const plan = createWearableVoiceActionPlan({
    intent,
    approvalState: snapshot.currentApproval,
    rawTranscript: '자비스 승인 token=hidden'
  });
  assert.equal(intent.intentName, 'approve');
  assert.equal(intent.privacy.rawTranscriptStored, false);
  assert.equal(plan.action, 'request_pc_confirmation');
  assert.equal(plan.rawTranscriptStored, false);
  const panelPcPlan = createWearableHudActionPlan({
    actionId: 'pc-confirm',
    approvalState: snapshot.currentApproval,
    command: '승인 PC 확인 요청'
  });
  assert.equal(panelPcPlan.action, 'request_pc_confirmation');
  assert.equal(panelPcPlan.path, plan.path);
  const panelRejectPlan = createWearableHudActionPlan({
    actionId: 'reject',
    approvalState: snapshot.currentApproval
  });
  assert.equal(panelRejectPlan.action, 'approval_decision');
  assert.equal(panelRejectPlan.body.decision, 'reject');
  assert.equal(snapshot.frame.lines.some((line) => line.text.includes('PC 확인 필요')), true);
  assert.equal(snapshot.frame.layoutContract.operatorFirst, true);
  assert.equal(snapshot.frame.actions.some((item) => item.label.includes('PC 확인')), true);
  assert.equal(snapshot.frame.context.some(([label, value]) => label === '허용' && value.includes('PC 확인 필요')), true);
  assert.equal(snapshot.frame.metrics.some((item) => item.label === '듣기'), true);
  assert.equal(snapshot.frame.context.some(([label]) => label === '판단'), true);

  const commandIntent = createWearableBrowserVoiceIntent({ transcript: '자비스 회의 녹음 시작 token=hidden' });
  const commandPlan = createWearableVoiceActionPlan({
    intent: commandIntent,
    rawTranscript: '자비스 회의 녹음 시작 token=hidden'
  });
  assert.equal(commandIntent.intentName, 'execute_command');
  assert.equal(commandPlan.action, 'stage_task');
  assert.equal(commandPlan.path, '/tasks');
  assert.equal(commandPlan.body.rawText.includes('자비스'), false);
  assert.equal(commandPlan.body.rawText.includes('hidden'), false);
  assert.match(commandPlan.body.rawText, /회의 녹음 시작/);
  let sentRequest = null;
  const execution = await executeWearableVoiceAction({
    plan: commandPlan,
    rawTranscript: '자비스 회의 녹음 시작 token=hidden',
    request: async (path, options) => {
      sentRequest = { path, options };
      return { taskId: 'task_wearable_voice_1', status: 'CREATED' };
    }
  });
  assert.equal(execution.status, 'sent');
  assert.equal(execution.taskId, 'task_wearable_voice_1');
  assert.equal(sentRequest.path, '/tasks');
  assert.equal(sentRequest.options.method, 'POST');
  assert.equal(sentRequest.options.auth, true);
  assert.equal(sentRequest.options.body.rawText.includes('hidden'), false);

  const quickPlan = createWearableQuickCommandPlan({ command: '현재 화면 캡처' });
  assert.equal(quickPlan.action, 'stage_task');
  assert.equal(quickPlan.path, '/tasks');
  assert.equal(quickPlan.body.rawText, '현재 화면 캡처');
  assert.equal(quickPlan.privacy.rawCommandStored, false);
  const panelCapturePlan = createWearableHudActionPlan({
    actionId: 'capture-screen',
    command: '현재 화면 캡처'
  });
  assert.equal(panelCapturePlan.action, 'stage_task');
  assert.equal(panelCapturePlan.body.rawText, '현재 화면 캡처');

  const pairingBody = createWearablePairingConfirmBody({
    pairing: { pairingId: 'pair_browser_1', pairingCode: '12345678' },
    deviceId: 'wearable glasses #1',
    deviceName: '안경 HUD'
  });
  assert.equal(pairingBody.deviceId, 'wearable_glasses_1');
  assert.equal(pairingBody.deviceName, '안경 HUD');
  assert.equal(pairingBody.pairingCode, '12345678');
  assert.equal(pairingBody.pairingId, 'pair_browser_1');

  const pairingRequests = [];
  const pairing = await pairWearableHudBrowser({
    deviceId: 'wearable_test',
    deviceName: 'JARVIS Wearable HUD',
    request: async (path, options) => {
      pairingRequests.push({ path, options });
      if (path === '/pairing/start') {
        return { pairingId: 'pair_browser_2', pairingCode: '87654321' };
      }
      return {
        success: true,
        deviceId: options.body.deviceId,
        deviceToken: 'paired-device-token',
        expiresAt: '2027-01-01T00:00:00.000Z',
        pairingId: options.body.pairingId
      };
    }
  });
  assert.equal(pairing.success, true);
  assert.equal(pairing.stage, 'confirmed');
  assert.equal(pairing.rawBridgeTokenStored, false);
  assert.equal(pairing.deviceToken, 'paired-device-token');
  assert.deepEqual(pairingRequests.map((item) => item.path), ['/pairing/start', '/pairing/confirm']);
  assert.equal(pairingRequests[0].options.auth, false);
  assert.equal(pairingRequests[1].options.body.pairingCode, '87654321');
});

