  assert.equal(schemaBundle.schemas.MemoryEvent.$id.includes('f-memory-event-union-v1'), true);
  assert.equal(schemaBundle.schemas.MemoryEvent.required.includes('learningFlags'), true);
  const fixtureCorpus = growthRuntime.memoryEventFixtureCorpus();
  assert.equal(fixtureCorpus.corpusVersion, 'f-memory-event-fixture-corpus-v1');
  assert.equal(fixtureCorpus.fixtureCount >= 18, true);
  assert.equal(fixtureCorpus.fixtures.some((item) => item.fixtureId === 'invalid.learning_flags_type' && item.expectedValid === false), true);
  const migrationCompatibility = growthRuntime.memoryEventMigrationCompatibilityReport();
  assert.equal(migrationCompatibility.reportVersion, 'f-memory-event-migration-compatibility-v1');
  assert.equal(migrationCompatibility.status, 'passed');
  assert.equal(migrationCompatibility.items.some((item) => item.migrationType === 'legacy-v0-to-current' && item.passed), true);
  const verifierMatrix = growthRuntime.memoryEventLearningVerifierSchemaMatrix();
  assert.equal(verifierMatrix.matrixVersion, 'f-g-learning-verifier-schema-matrix-v1');
  assert.equal(verifierMatrix.linked, true);
  assert.equal(verifierMatrix.status, 'passed');
  const telemetry = growthRuntime.ingestor.ingestTelemetry();
  assert.equal(telemetry.telemetryVersion, 'f-memory-event-ingest-telemetry-v1');
  assert.equal(telemetry.storedCount >= 2, true);
  assert.equal(telemetry.byVariant.feedback_do_not_remember >= 1, true);
  const backpressure = growthRuntime.ingestor.backpressurePolicy({ maxLearningQueue: 100 });
  assert.equal(backpressure.policyVersion, 'f-memory-event-ingest-backpressure-policy-v1');
  assert.equal(backpressure.status, 'ok');
  const operationalCorpus = growthRuntime.ingestor.anonymizedOperationalCorpus({ limit: 10 });
