await test('F failure guardrail reviews persist in SQLite and restore recurrence dashboard', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-f-failure-persistence-'));
  const storeOptions = {
    dbPath: join(dir, 'growth.sqlite'),
    reviewDir: join(dir, 'reviews'),
    backupDir: join(dir, 'backups')
  };
  let store = new SqliteMemoryStore(storeOptions);
  try {
    const { growthRuntime } = createAgRuntime({ memoryStore: store });
    growthRuntime.ingestor.ingest({
      eventId: 'evt_failure_persist_policy',
      eventType: 'policy.blocked',
      taskId: 'task_failure_persist_policy',
      payload: {
        rawText: '밴드에 외부 전송해',
        reason: '외부 전송은 PC 승인 필요',
        reasonCode: 'E_EXTERNAL_TRANSFER_PC_ONLY',
        actionType: 'UPLOAD_FILE'
      },
      learningFlags: { doNotRemember: false, containsSensitiveData: false },
      trustBoundary: { userProvided: true, externalContent: false, systemGenerated: false }
    });
    const failure = growthRuntime.latestReview().failureLessons[0];
    const reviewed = growthRuntime.reviewFailureGuardrail(failure.failureId, {
      decision: 'update',
      reviewedBy: 'sqlite-reviewer',
      reason: 'persist guardrail review',
      patch: {
        guardrailChecklist: [...failure.guardrailChecklist, 'persisted_review_loaded_before_plan']
      }
    });
    assert.equal(reviewed.success, true);
    assert.equal(reviewed.persisted, true);
    assert.equal(growthRuntime.storageStatus().counts.failureGuardrailReviews, 1);
    store.close();
    store = null;

    store = new SqliteMemoryStore(storeOptions);
    const { growthRuntime: restoredRuntime } = createAgRuntime({ memoryStore: store });
    const restoredFailure = restoredRuntime.latestReview().failureLessons.find((item) => item.failureId === failure.failureId);
    assert.equal(restoredFailure.guardrailReview.reviewedBy, 'sqlite-reviewer');
    assert.equal(restoredFailure.guardrailChecklist.includes('persisted_review_loaded_before_plan'), true);
    const restoredGuardrails = restoredRuntime.planningFailureGuardrails('밴드');
    assert.equal(restoredGuardrails.recurrenceDashboard.dashboardVersion, 'f-failure-recurrence-dashboard-v1');
    assert.equal(restoredGuardrails.recurrenceDashboard.reviewedGuardrailCount, 1);
  } finally {
    store?.close();
    await rm(dir, { recursive: true, force: true });
  }
});

