      assert.equal(batchDecision.appliedCount, 1);
      const status = await getJson(`${baseUrl}/storage/status`);
      assert.equal(status.schemaVersion, 5);
      assert.equal(status.integrity.status, 'ok');
      assert.equal(status.counts.growthTrendSnapshots >= 1, true);
      const trendArchive = await getJson(`${baseUrl}/trends/archive`);
      assert.equal(trendArchive.archiveVersion, 'f-growth-trend-archive-v1');
      assert.equal(trendArchive.persisted, true);
      assert.equal(trendArchive.countsByType.hygiene >= 1, true);
      const backup = await postJson(`${baseUrl}/storage/backup`, { backupId: 'api-backup-1' });
      assert.equal(backup.success, true);
      const keyProvider = await getJson(`${baseUrl}/storage/encryption-key`);
      assert.equal(keyProvider.providerVersion, 'f-storage-encryption-key-provider-v1');
      const backupLocationPolicy = await getJson(`${baseUrl}/storage/backup-location-policy`);
      assert.equal(backupLocationPolicy.policyVersion, 'f-storage-backup-location-policy-v1');
      assert.equal(backupLocationPolicy.encryptedBackupRequired, true);
      const atRestPolicy = await getJson(`${baseUrl}/storage/at-rest-encryption-policy`);
      assert.equal(atRestPolicy.policyVersion, 'f-storage-at-rest-encryption-deployment-policy-v1');
      assert.equal(atRestPolicy.controls.wormMirrorRequired, true);
      const encryptedBackup = await postJson(`${baseUrl}/storage/encrypted-backup`, { backupId: 'api-sealed-backup-1' });
      assert.equal(encryptedBackup.backupVersion, 'f-storage-encrypted-backup-v1');
      assert.equal(encryptedBackup.success, true);
      const encryptedDrill = await postJson(`${baseUrl}/storage/restore-drill`, { backupPath: encryptedBackup.filePath });
      assert.equal(encryptedDrill.drillVersion, 'f-storage-encrypted-restore-drill-v1');
