await test('B/D/E/F/G write module audit events to JSONL logs', async () => {
  const dir = await mkdtemp(join(tmpdir(), 'jarvis-audit-'));
  try {
    const { bridgeRuntime, verificationRuntime } = createAgRuntime({
      allowedRoots: [dir],
      outputPath: join(dir, 'audit-output.txt'),
      auditRoot: dir
    });
    const pairing = bridgeRuntime.pairing.start();
    const confirmed = bridgeRuntime.pairing.confirm({
      deviceId: 'mobile_lcb_001',
      deviceName: 'LCB Galaxy',
      pairingCode: pairing.pairingCode
    });
    const created = bridgeRuntime.createTask({ rawText: '감사 로그 파일 만들어', token: confirmed.deviceToken });
    const approved = await bridgeRuntime.decideApproval({
      approvalId: created.approvalId,
      decision: ApprovalDecision.APPROVE,
      token: confirmed.deviceToken
    });
    await bridgeRuntime.confirmExecutionHandoff({ handoffId: approved.handoffId, token: confirmed.deviceToken });
    bridgeRuntime.recordFeedback({
      token: confirmed.deviceToken,
      feedback: { taskId: created.taskId, feedbackType: 'result_good', text: '좋아' }
    });
    verificationRuntime.runRegressionSuite();

    const bridgeEvents = await readJsonl(join(dir, 'bridge-audit.jsonl'));
    const policyEvents = await readJsonl(join(dir, 'policy-audit.jsonl'));
    const pcEvents = await readJsonl(join(dir, 'pc-agent-audit.jsonl'));
    const executionEvents = await readJsonl(join(dir, 'executions.jsonl'));
    const evidenceEvents = await readJsonl(join(dir, 'evidence.jsonl'));
    const executionMemoryEvents = await readJsonl(join(dir, 'memory-events.jsonl'));
    const memoryEvents = await readJsonl(join(dir, 'memory-audit.jsonl'));
    const verificationEvents = await readJsonl(join(dir, 'verification.jsonl'));

    assert.ok(bridgeEvents.some((event) => event.event === 'approval.decision.received'));
    assert.ok(bridgeEvents.some((event) => event.event === 'execution.handoff.confirmed'));
    assert.equal(bridgeEvents.every((event) => event.hash && event.previousHash && event.category && event.severity), true);
    assert.equal(bridgeRuntime.auditLog.verifyChain().valid, true);
    assert.equal(bridgeRuntime.auditLog.summary({ category: 'access' }).byCategory.access > 0, true);
    assert.equal(bridgeRuntime.auditLog.summary({ severity: 'warning' }).chain.valid, true);
    assert.ok(policyEvents.some((event) => event.event === 'policy.evaluated'));
    assert.ok(policyEvents.some((event) => event.event === 'capability.issued'));
    assert.ok(pcEvents.some((event) => event.event === 'execution.completed'));
    assert.ok(executionEvents.some((event) => event.status === TaskStatus.COMPLETED));
    assert.ok(evidenceEvents.some((event) => event.status === 'success'));
    assert.ok(executionMemoryEvents.some((event) => event.eventType === 'execution.completed'));
    assert.ok(memoryEvents.some((event) => event.event === 'memory.event.stored'));
    assert.ok(verificationEvents.some((event) => event.event === 'verification.completed'));
    assert.ok(verificationEvents.some((event) => event.event === 'regression.completed'));
  } finally {
    await rm(dir, { recursive: true, force: true });
  }
});

