    await mkdir(join(evidenceDir, 'pc-agent'), { recursive: true });
    await mkdir(dirname(workflowPath), { recursive: true });

    await writeFile(join(distDir, 'core-service-package', 'install-all.ps1'), 'Write-Host "core install"\n', 'utf8');
