    await writeFile(workflowPath, 'name: JARVIS Product Evidence\n', 'utf8');
    await writeFile(join(distDir, 'worm-promotion', 'manifest.json'), JSON.stringify({
      status: 'ready-for-external-worm-promotion',
      bundleHash: 'a'.repeat(64),
      artifactCount: 12,
      externalSync: { status: 'not-configured-local-staging-only' }
    }), 'utf8');
    await writeFile(join(distDir, 'windows-admin-install-attempts.json'), JSON.stringify({
      status: 'verified',
      elevated: true
    }), 'utf8');

    for (const fileName of ['installed-service-verification.json', 'installed-service-smoke.json', 'installed-service-soak.json']) {
      await writeFile(join(evidenceDir, 'core', fileName), JSON.stringify({ status: 'passed' }), 'utf8');
    }
    await writeFile(join(evidenceDir, 'core', 'package-manifest.json'), JSON.stringify({ packageVersion: 'a-core-service-package-v1' }), 'utf8');
    await writeFile(join(evidenceDir, 'pc-agent', 'service-smoke-report.json'), JSON.stringify({ status: 'passed' }), 'utf8');
    await writeFile(join(evidenceDir, 'pc-agent', 'install-release-report.json'), JSON.stringify({ status: 'passed-with-warnings' }), 'utf8');
    await writeFile(join(evidenceDir, 'pc-agent', 'release-evidence.json'), JSON.stringify({ status: 'ready-with-warnings' }), 'utf8');
    await writeFile(join(evidenceDir, 'pc-agent', 'package-manifest.json'), JSON.stringify({ packageVersion: 'b-pc-agent-installer-package-v1' }), 'utf8');
    await writeFile(join(evidenceDir, 'field-validation-run-summary.json'), `\uFEFF${JSON.stringify({
      reportVersion: 'ag-field-validation-run-v1',
      status: 'passed',
      generatedAt: '2030-01-01T00:00:00.000Z',
      transcriptPath: join(evidenceDir, 'transcripts', 'field-validation.log'),
      steps: [{ id: 'administrator-shell', status: 'pass' }]
    })}`, 'utf8');

    const report = await runFieldValidationKit({
      workspaceRoot: root,
      distDir,
      outputDir,
      evidenceDir,
      jsonPath: join(distDir, 'field-validation-kit-report.json'),
      markdownPath: join(distDir, 'field-validation-kit-report.md'),
      workflowPath
    });

    assert.equal(report.reportVersion, 'ag-field-validation-kit-v1');
    assert.equal(report.status, 'field-evidence-verified');
    assert.equal(report.coreAdminEvidence.status, 'verified');
    assert.equal(report.pcAgentAdminEvidence.status, 'verified');
    assert.equal(report.fieldRunSummary.status, 'passed');
    assert.equal(report.wormPromotion.status, 'ready-for-external-worm-promotion');
    assert.equal(report.fieldValidationKit.rawScriptBodiesStored, false);
    assert.equal(report.fieldValidationKit.rawAdminTokenStored, false);
    assert.equal(report.checks.find((check) => check.checkId === 'required_admin_scripts_present').passed, true);
    assert.equal(report.checks.find((check) => check.checkId === 'field_run_summary_passed').passed, true);
    assert.equal(report.checks.find((check) => check.checkId === 'core_admin_evidence_verified').passed, true);
    assert.equal(await pathExists(join(outputDir, 'run-field-validation.ps1')), true);
    assert.equal(await pathExists(join(outputDir, 'start-field-validation-admin.ps1')), true);
