    assert.equal(report.generatedArtifacts.rawWormCredentialStored, false);
    assert.equal(report.checks.find((item) => item.checkId === 'raw_secret_or_command_not_stored').passed, true);
    assert.equal(await pathExists(join(targetDir, 'field-validation-run-summary.json')), true);
