await test('A-G external WORM sync proof enforces append-only bundle promotion', async () => {
  const root = await mkdtemp(join(tmpdir(), 'jarvis-external-worm-sync-'));
  try {
    const wormDir = join(root, 'dist', 'worm-promotion');
    const manifestPath = join(wormDir, 'manifest.json');
    const manifestHashPath = join(wormDir, 'manifest.sha256');
    const proofPath = join(wormDir, 'external-sync-proof.json');
    const proofMarkdownPath = join(wormDir, 'external-sync-proof.md');
    const externalDir = join(root, 'worm-target');
    const bundleHash = 'b'.repeat(64);
    await mkdir(wormDir, { recursive: true });
    await writeFile(manifestPath, JSON.stringify({
      manifestVersion: 'jarvis-ci-worm-promotion-v1',
      status: 'ready-for-external-worm-promotion',
      bundleHash,
      artifactCount: 3,
      localAppendOnlyStaging: {
        bundleDir: join(wormDir, 'bundles', bundleHash)
      }
    }, null, 2), 'utf8');
    await writeFile(manifestHashPath, `${bundleHash}  manifest.json\n`, 'utf8');

    const unconfigured = await runExternalWormSync({
      manifestPath,
      manifestHashPath,
      outputPath: proofPath,
      markdownPath: proofMarkdownPath
    });
    assert.equal(unconfigured.proofVersion, 'jarvis-external-worm-sync-proof-v1');
    assert.equal(unconfigured.status, 'not-configured-local-staging-only');
    assert.equal(unconfigured.rawCredentialsStored, false);
    assert.equal(unconfigured.rawCommandStored, false);

    const synced = await runExternalWormSync({
      manifestPath,
      manifestHashPath,
      outputPath: proofPath,
      markdownPath: proofMarkdownPath,
      externalDir
    });
    assert.equal(synced.status, 'synced');
    assert.equal(synced.provider, 'local-append-only-directory');
    assert.equal(synced.bundleHash, bundleHash);
    assert.equal(synced.details.manifestCopy.copied, true);
    assert.equal(synced.details.manifestCopy.matchedExisting, true);
    assert.equal(await pathExists(join(externalDir, bundleHash, 'manifest.json')), true);
    assert.equal(await pathExists(join(externalDir, bundleHash, 'manifest.sha256')), true);
    assert.equal(await pathExists(join(externalDir, bundleHash, 'sync-proof.json')), true);

    const repeated = await runExternalWormSync({
      manifestPath,
      manifestHashPath,
      outputPath: proofPath,
      markdownPath: proofMarkdownPath,
      externalDir
    });
    assert.equal(repeated.status, 'already-synced');
    assert.equal(repeated.details.manifestCopy.copied, false);
    assert.equal(repeated.details.manifestCopy.matchedExisting, true);

    await writeFile(join(externalDir, bundleHash, 'manifest.json'), '{"tampered":true}\n', 'utf8');
    const blocked = await runExternalWormSync({
      manifestPath,
      manifestHashPath,
      outputPath: proofPath,
      markdownPath: proofMarkdownPath,
      externalDir
    });
    assert.equal(blocked.status, 'blocked-existing-bundle-mismatch');
    assert.equal(blocked.details.manifestCopy.matchedExisting, false);
    assert.match(await readFile(join(externalDir, bundleHash, 'manifest.json'), 'utf8'), /tampered/);
    assert.match(await readFile(proofMarkdownPath, 'utf8'), /External WORM Sync Proof/);
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

await test('A-G WORM target prepare validates append-only target before sync', async () => {
  const root = await mkdtemp(join(tmpdir(), 'jarvis-worm-target-'));
  try {
    const distDir = join(root, 'dist');
    const wormDir = join(distDir, 'worm-promotion');
    const targetDir = join(root, 'worm-target');
    const outputDir = join(distDir, 'worm-target');
    const manifestPath = join(wormDir, 'manifest.json');
    const manifestHashPath = join(wormDir, 'manifest.sha256');
    const proofPath = join(wormDir, 'external-sync-proof.json');
    const proofMarkdownPath = join(wormDir, 'external-sync-proof.md');
    const bundleHash = 'f'.repeat(64);
    await mkdir(wormDir, { recursive: true });
    await writeFile(manifestPath, JSON.stringify({
      manifestVersion: 'jarvis-ci-worm-promotion-v1',
      status: 'ready-for-external-worm-promotion',
      bundleHash,
      artifactCount: 9
    }, null, 2), 'utf8');
    await writeFile(manifestHashPath, `${bundleHash}  manifest.json\n`, 'utf8');
    await writeFile(proofPath, JSON.stringify({
      proofVersion: 'jarvis-external-worm-sync-proof-v1',
      status: 'not-configured-local-staging-only',
      provider: 'not-configured',
      rawCredentialsStored: false,
      rawCommandStored: false
    }), 'utf8');

    const ready = await runWormTargetPrepare({
      workspaceRoot: root,
      targetDir,
      distDir,
      outputDir,
      jsonPath: join(distDir, 'worm-target-report.json'),
      markdownPath: join(distDir, 'worm-target-report.md')
    });
    assert.equal(ready.reportVersion, 'jarvis-worm-target-prepare-v1');
    assert.equal(ready.status, 'ready-for-worm-sync');
    assert.equal(ready.checks.find((item) => item.checkId === 'target_outside_dist').passed, true);
    assert.equal(ready.checks.find((item) => item.checkId === 'append_only_policy_documented').passed, true);
    assert.match(ready.summary.syncCommand, /ops:worm-sync/);
    assert.equal(await pathExists(join(targetDir, '.jarvis-worm-target.json')), true);
    assert.equal(await pathExists(join(targetDir, 'APPEND_ONLY_POLICY.md')), true);
    assert.match(await readFile(join(distDir, 'worm-target-report.md'), 'utf8'), /WORM Target Prepare/);

    await runExternalWormSync({
      manifestPath,
      manifestHashPath,
      outputPath: proofPath,
      markdownPath: proofMarkdownPath,
      externalDir: targetDir
    });
    const synced = await runWormTargetPrepare({
      workspaceRoot: root,
      targetDir,
      distDir,
      outputDir,
      jsonPath: join(distDir, 'worm-target-report-synced.json'),
      markdownPath: join(distDir, 'worm-target-report-synced.md')
    });
    assert.equal(synced.status, 'synced');
    assert.equal(synced.summary.proofMatchesTarget, true);

    await writeFile(join(targetDir, bundleHash, 'manifest.json'), '{"tampered":true}\n', 'utf8');
    const blocked = await runWormTargetPrepare({
      workspaceRoot: root,
      targetDir,
      distDir,
      outputDir,
      jsonPath: join(distDir, 'worm-target-report-blocked.json'),
      markdownPath: join(distDir, 'worm-target-report-blocked.md')
    });
    assert.equal(blocked.status, 'blocked-existing-bundle-mismatch');
    assert.equal(blocked.checks.find((item) => item.checkId === 'existing_bundle_manifest_matches').passed, false);

    const distTarget = await runWormTargetPrepare({
      workspaceRoot: root,
      targetDir: join(distDir, 'bad-worm-target'),
      distDir,
      outputDir,
      jsonPath: join(distDir, 'worm-target-report-dist-target.json'),
      markdownPath: join(distDir, 'worm-target-report-dist-target.md')
    });
    assert.equal(distTarget.status, 'blocked-target-not-ready');
    assert.equal(distTarget.checks.find((item) => item.checkId === 'target_outside_dist').passed, false);
  } finally {
    await rm(root, { recursive: true, force: true });
  }
});

